# every test module (a fixture each, and the backends), run side by side: the suite takes as long as its slowest world
import io, os, sys, unittest
from concurrent.futures import ProcessPoolExecutor

HERE = os.path.dirname(os.path.abspath(__file__))


def run(name):
    out = io.StringIO()
    got = unittest.TextTestRunner(stream=out, verbosity=0).run(unittest.defaultTestLoader.discover(HERE, pattern=name))
    return name, got.testsRun, len(got.failures) + len(got.errors), len(got.skipped), out.getvalue()


if __name__ == "__main__":
    names = sorted(n for n in os.listdir(HERE) if n.startswith("test_") and n.endswith(".py"))
    ran = failed = skipped = 0
    with ProcessPoolExecutor() as pool:
        for name, r, f, s, text in pool.map(run, names):
            ran, failed, skipped = ran + r, failed + f, skipped + s
            print(("FAIL " if f else "ok   ") + name + ": " + str(r) + " ran, " + str(f) + " failed, " + str(s) + " skipped", flush=True)
            if f:
                print(text, flush=True)
    print(str(ran - failed - skipped) + " passed, " + str(failed) + " failed, " + str(skipped) + " skipped of " + str(ran))
    sys.exit(1 if failed else 0)
